(() => {
    const REQUIRED_SANDBOX = [
        "allow-scripts",
        "allow-same-origin",
        "allow-popups",
        "allow-forms",
        "allow-presentation"
    ];

    const REQUIRED_ALLOW = [
        "autoplay",
        "fullscreen",
        "encrypted-media",
        "picture-in-picture"
    ];

    function patchIframe(frame) {
        if (!(frame instanceof HTMLIFrameElement)) return;

        let sandboxChanged = false;

        if (frame.hasAttribute("sandbox")) {
            const tokens = new Set(
                (frame.getAttribute("sandbox") || "")
                    .split(/\s+/)
                    .filter(Boolean)
            );

            for (const permission of REQUIRED_SANDBOX) {
                if (!tokens.has(permission)) {
                    tokens.add(permission);
                    sandboxChanged = true;
                }
            }

            if (sandboxChanged) {
                frame.setAttribute(
                    "sandbox",
                    Array.from(tokens).join(" ")
                );
            }
        }

        const currentAllow = (frame.getAttribute("allow") || "")
            .split(";")
            .map(v => v.trim())
            .filter(Boolean);

        const allowNames = new Set(
            currentAllow.map(v => v.split(/\s+/)[0])
        );

        for (const permission of REQUIRED_ALLOW) {
            if (!allowNames.has(permission)) {
                currentAllow.push(permission);
            }
        }

        frame.setAttribute("allow", currentAllow.join("; "));
        frame.setAttribute("allowfullscreen", "true");

        /*
         * Sandbox permissions are applied when the iframe navigates.
         * Reload the frame once after changing them.
         */
        if (
            sandboxChanged &&
            frame.src &&
            frame.dataset.notmeSandboxReloaded !== "1"
        ) {
            frame.dataset.notmeSandboxReloaded = "1";

            const src = frame.src;

            setTimeout(() => {
                if (!frame.isConnected) return;

                try {
                    frame.src = src;
                } catch (_) {}
            }, 50);
        }
    }

    function scan(root = document) {
        try {
            root.querySelectorAll("iframe").forEach(patchIframe);
        } catch (_) {}
    }

    scan();

    const observer = new MutationObserver(mutations => {
        for (const mutation of mutations) {
            if (
                mutation.type === "attributes" &&
                mutation.target instanceof HTMLIFrameElement
            ) {
                patchIframe(mutation.target);
            }

            for (const node of mutation.addedNodes) {
                if (!(node instanceof Element)) continue;

                if (node instanceof HTMLIFrameElement) {
                    patchIframe(node);
                }

                scan(node);
            }
        }
    });

    observer.observe(
        document.documentElement,
        {
            childList: true,
            subtree: true,
            attributes: true,
            attributeFilter: ["sandbox", "src"]
        }
    );

    window.__notmeVideoSandboxObserver = observer;
})();
